// Provide default metadata or fetch from an existing trigger/config node
const meta = {
  period_start: '2022-12-01',
  period_end: '2022-12-31',
  chatInput: 'Analyze the SKU weekly sales performance.',
};

// Excel stores dates as serial numbers (days since 1899-12-30)
const toIso = (v) => {
  if (typeof v === 'number') return new Date(Math.round((v - 25569) * 86400000)).toISOString().slice(0, 10);
  const d = new Date(v);
  return isNaN(d) ? null : d.toISOString().slice(0, 10);
};

const rows = $input.all()
  .map((i) => ({ ...i.json, Week_Start_Date: toIso(i.json.Week_Start_Date) }))
  .filter((r) => r.Week_Start_Date && r.Week_Start_Date >= meta.period_start && r.Week_Start_Date <= meta.period_end);

const chatInput = meta.chatInput + '\n\nSKU weekly sales data for ' + meta.period_start + ' to ' + meta.period_end + ' (' + rows.length + ' rows, JSON):\n' + JSON.stringify(rows);

return [{ json: { ...meta, rows_count: rows.length, rows, chatInput, text: chatInput } }];
